# OCP
cloud_hostings = BuiltIn().get_variable_value("${tl.cloud_hostings}")
OCP_CONNECTION_DETAILS: Optional[List[Any]]

if cloud_hostings:
    OCP_CONNECTION_DETAILS = list()
    for cloud_hosting in cloud_hostings:
        ssh_connection_details = cloud_hosting.master_node.ssh_connection_details
        if ssh_connection_details.addr not in [detail.addr for detail in OCP_CONNECTION_DETAILS]:
            OCP_CONNECTION_DETAILS.append(ssh_connection_details)
else:
    OCP_CONNECTION_DETAILS = None
